"""Supply chain order fulfilment: the TPC-H benchmark's eight tables (generated by DuckDB's own dbgen, no download) plus four tables computed from them.

TPC-H models a wholesale supplier: customers place orders of line items, each line is a part supplied by a supplier, and nations group
into regions. The computed tables answer business questions across several of those tables (supplier on-time delivery, customer value,
order fulfilment, part supply cover), which is what gives the lineage more than one hop.
"""
from __future__ import annotations

import duckdb
import pandas as pd

from app.services.v2.data_import.model import Bundle, Derived, Link, Source, Table

SCALE = 0.001
ORDERS = 1000
RAW = ["region", "nation", "supplier", "customer", "part", "partsupp", "orders", "lineitem"]

LABELS = {
    "region": ("Region", "地区", "供应链覆盖的五大地区", ["r_regionkey"], {"r_regionkey": "地区编号", "r_name": "地区名称", "r_comment": "备注"}),
    "nation": ("Nation", "国家", "客户和供应商所在的国家", ["n_nationkey"], {"n_nationkey": "国家编号", "n_name": "国家名称", "n_regionkey": "所属地区", "n_comment": "备注"}),
    "supplier": ("Supplier", "供应商", "提供零件的供应商", ["s_suppkey"], {"s_suppkey": "供应商编号", "s_name": "供应商名称", "s_address": "地址", "s_nationkey": "所属国家", "s_phone": "电话",
                                                                 "s_acctbal": "账户余额", "s_comment": "备注"}),
    "customer": ("Customer", "客户", "下订单的客户", ["c_custkey"], {"c_custkey": "客户编号", "c_name": "客户名称", "c_address": "地址", "c_nationkey": "所属国家", "c_phone": "电话",
                                                            "c_acctbal": "账户余额", "c_mktsegment": "市场细分", "c_comment": "备注"}),
    "part": ("Part", "零件", "可供应的零件", ["p_partkey"], {"p_partkey": "零件编号", "p_name": "零件名称", "p_mfgr": "制造商", "p_brand": "品牌", "p_type": "类型", "p_size": "尺寸",
                                                      "p_container": "包装", "p_retailprice": "零售价", "p_comment": "备注"}),
    "partsupp": ("PartSupplier", "供货关系", "一个供应商供应一种零件的可用数量和成本", ["ps_partkey", "ps_suppkey"], {"ps_partkey": "零件", "ps_suppkey": "供应商", "ps_availqty": "可用数量",
                                                                                                    "ps_supplycost": "供货成本", "ps_comment": "备注"}),
    "orders": ("Order", "订单", "客户的订单", ["o_orderkey"], {"o_orderkey": "订单编号", "o_custkey": "客户", "o_orderstatus": "订单状态", "o_totalprice": "订单总价", "o_orderdate": "下单日期",
                                                           "o_orderpriority": "优先级", "o_clerk": "经办人", "o_shippriority": "发货优先级", "o_comment": "备注"}),
    "lineitem": ("LineItem", "订单行", "订单里的一行：某个供应商供应的某个零件", ["l_orderkey", "l_linenumber"], {
        "l_orderkey": "订单", "l_partkey": "零件", "l_suppkey": "供应商", "l_linenumber": "行号", "l_quantity": "数量", "l_extendedprice": "金额", "l_discount": "折扣", "l_tax": "税",
        "l_returnflag": "退货标记", "l_linestatus": "行状态", "l_shipdate": "发货日期", "l_commitdate": "承诺日期", "l_receiptdate": "签收日期", "l_shipinstruct": "发货方式",
        "l_shipmode": "运输方式", "l_comment": "备注"}),
}

FKS = [("nation", "n_regionkey", "region", "r_regionkey"), ("supplier", "s_nationkey", "nation", "n_nationkey"), ("customer", "c_nationkey", "nation", "n_nationkey"),
       ("partsupp", "ps_partkey", "part", "p_partkey"), ("partsupp", "ps_suppkey", "supplier", "s_suppkey"), ("orders", "o_custkey", "customer", "c_custkey"),
       ("lineitem", "l_orderkey", "orders", "o_orderkey"), ("lineitem", "l_partkey", "part", "p_partkey"), ("lineitem", "l_suppkey", "supplier", "s_suppkey")]

# Rules from the TPC-H specification, stated as constraints on the properties.
RAW_RULES = {
    "lineitem": {"l_discount": {"minimum": 0, "maximum": 0.1}, "l_tax": {"minimum": 0, "maximum": 0.08}, "l_quantity": {"minimum": 1, "maximum": 50},
                 "l_returnflag": {"enum": ["R", "A", "N"]}, "l_linestatus": {"enum": ["O", "F"]}},
    "orders": {"o_orderstatus": {"enum": ["F", "O", "P"]}}, "part": {"p_size": {"minimum": 1, "maximum": 50}},
    "customer": {"c_mktsegment": {"enum": ["AUTOMOBILE", "BUILDING", "FURNITURE", "HOUSEHOLD", "MACHINERY"]}},
}

DERIVED = [
    {"name": "supplier_performance", "type": "SupplierPerformance", "label": "供应商履约", "key": "supplier_key", "of": ("supplier", "s_suppkey"),
     "description": "每个供应商的订单行数、准时签收率、平均延误天数和销售额（由订单行、供应商、国家计算）",
     "inputs": ["lineitem", "supplier", "nation"],
     "sql": """SELECT s.s_suppkey AS supplier_key, s.s_name AS supplier_name, n.n_name AS nation_name, COUNT(*) AS line_count,
       SUM(CASE WHEN l.l_receiptdate <= l.l_commitdate THEN 1 ELSE 0 END) AS on_time_lines,
       ROUND(AVG(CASE WHEN l.l_receiptdate <= l.l_commitdate THEN 1.0 ELSE 0.0 END), 4) AS on_time_rate,
       ROUND(AVG(DATEDIFF('day', l.l_commitdate, l.l_receiptdate)), 2) AS avg_delay_days,
       ROUND(SUM(l.l_extendedprice * (1 - l.l_discount)), 2) AS revenue
FROM lineitem l JOIN supplier s ON s.s_suppkey = l.l_suppkey JOIN nation n ON n.n_nationkey = s.s_nationkey
GROUP BY s.s_suppkey, s.s_name, n.n_name""",
     "columns": {"supplier_key": ["supplier.s_suppkey"], "supplier_name": ["supplier.s_name"], "nation_name": ["nation.n_name"], "line_count": ["lineitem.l_orderkey"],
                 "on_time_lines": ["lineitem.l_receiptdate", "lineitem.l_commitdate"], "on_time_rate": ["lineitem.l_receiptdate", "lineitem.l_commitdate"],
                 "avg_delay_days": ["lineitem.l_receiptdate", "lineitem.l_commitdate"], "revenue": ["lineitem.l_extendedprice", "lineitem.l_discount"]},
     "labels": {"supplier_key": "供应商", "supplier_name": "供应商名称", "nation_name": "国家", "line_count": "订单行数", "on_time_lines": "准时签收行数", "on_time_rate": "准时签收率",
                "avg_delay_days": "平均延误天数", "revenue": "销售额"},
     "rules": {"on_time_rate": {"minimum": 0.5}}},
    {"name": "customer_value", "type": "CustomerValue", "label": "客户价值", "key": "customer_key", "of": ("customer", "c_custkey"),
     "description": "每个客户的订单数、累计消费、平均订单金额和最近下单日期（由客户、订单、国家计算）", "inputs": ["customer", "orders", "nation"],
     "sql": """SELECT c.c_custkey AS customer_key, c.c_name AS customer_name, n.n_name AS nation_name, c.c_mktsegment AS market_segment, COUNT(o.o_orderkey) AS order_count,
       ROUND(SUM(o.o_totalprice), 2) AS total_spent, ROUND(AVG(o.o_totalprice), 2) AS avg_order_value, MAX(o.o_orderdate) AS last_order_date
FROM customer c JOIN nation n ON n.n_nationkey = c.c_nationkey LEFT JOIN orders o ON o.o_custkey = c.c_custkey
GROUP BY c.c_custkey, c.c_name, n.n_name, c.c_mktsegment""",
     "columns": {"customer_key": ["customer.c_custkey"], "customer_name": ["customer.c_name"], "nation_name": ["nation.n_name"], "market_segment": ["customer.c_mktsegment"],
                 "order_count": ["orders.o_orderkey"], "total_spent": ["orders.o_totalprice"], "avg_order_value": ["orders.o_totalprice"], "last_order_date": ["orders.o_orderdate"]},
     "labels": {"customer_key": "客户", "customer_name": "客户名称", "nation_name": "国家", "market_segment": "市场细分", "order_count": "订单数", "total_spent": "累计消费",
                "avg_order_value": "平均订单金额", "last_order_date": "最近下单日期"}, "rules": {}},
    {"name": "order_fulfillment", "type": "OrderFulfillment", "label": "订单履约", "key": "order_key", "of": ("orders", "o_orderkey"),
     "description": "每个订单的行数、晚于承诺日期签收的行数和从下单到最后签收的天数（由订单、订单行计算）", "inputs": ["orders", "lineitem"],
     "sql": """SELECT o.o_orderkey AS order_key, o.o_orderstatus AS order_status, o.o_orderpriority AS priority, COUNT(*) AS line_count,
       SUM(CASE WHEN l.l_receiptdate > l.l_commitdate THEN 1 ELSE 0 END) AS late_lines, MIN(l.l_shipdate) AS first_ship_date, MAX(l.l_receiptdate) AS last_receipt_date,
       DATEDIFF('day', o.o_orderdate, MAX(l.l_receiptdate)) AS days_to_deliver
FROM orders o JOIN lineitem l ON l.l_orderkey = o.o_orderkey GROUP BY o.o_orderkey, o.o_orderstatus, o.o_orderpriority, o.o_orderdate""",
     "columns": {"order_key": ["orders.o_orderkey"], "order_status": ["orders.o_orderstatus"], "priority": ["orders.o_orderpriority"], "line_count": ["lineitem.l_linenumber"],
                 "late_lines": ["lineitem.l_receiptdate", "lineitem.l_commitdate"], "first_ship_date": ["lineitem.l_shipdate"], "last_receipt_date": ["lineitem.l_receiptdate"],
                 "days_to_deliver": ["orders.o_orderdate", "lineitem.l_receiptdate"]},
     "labels": {"order_key": "订单", "order_status": "订单状态", "priority": "优先级", "line_count": "行数", "late_lines": "晚签收行数", "first_ship_date": "首次发货日期",
                "last_receipt_date": "最后签收日期", "days_to_deliver": "交付天数"}, "rules": {"days_to_deliver": {"maximum": 150}}},
    {"name": "part_supply_risk", "type": "PartSupplyRisk", "label": "零件供货风险", "key": "part_key", "of": ("part", "p_partkey"),
     "description": "每种零件的供应商数、可用数量、需求数量和供应覆盖倍数（由零件、供货关系、订单行计算）", "inputs": ["part", "partsupp", "lineitem"],
     "sql": """WITH supply AS (SELECT ps_partkey, COUNT(*) AS supplier_count, SUM(ps_availqty) AS available_qty, AVG(ps_supplycost) AS avg_supply_cost FROM partsupp GROUP BY ps_partkey),
     demand AS (SELECT l_partkey, SUM(l_quantity) AS demand_qty FROM lineitem GROUP BY l_partkey)
SELECT p.p_partkey AS part_key, p.p_name AS part_name, p.p_brand AS brand, s.supplier_count, s.available_qty, ROUND(s.avg_supply_cost, 2) AS avg_supply_cost,
       COALESCE(d.demand_qty, 0) AS demand_qty, ROUND(s.available_qty / NULLIF(COALESCE(d.demand_qty, 0), 0), 2) AS coverage_ratio
FROM part p JOIN supply s ON s.ps_partkey = p.p_partkey LEFT JOIN demand d ON d.l_partkey = p.p_partkey""",
     "columns": {"part_key": ["part.p_partkey"], "part_name": ["part.p_name"], "brand": ["part.p_brand"], "supplier_count": ["partsupp.ps_suppkey"], "available_qty": ["partsupp.ps_availqty"],
                 "avg_supply_cost": ["partsupp.ps_supplycost"], "demand_qty": ["lineitem.l_quantity"], "coverage_ratio": ["partsupp.ps_availqty", "lineitem.l_quantity"]},
     "labels": {"part_key": "零件", "part_name": "零件名称", "brand": "品牌", "supplier_count": "供应商数", "available_qty": "可用数量", "avg_supply_cost": "平均供货成本",
                "demand_qty": "需求数量", "coverage_ratio": "供应覆盖倍数"}, "rules": {"coverage_ratio": {"minimum": 1}}},
]


def load() -> Bundle:
    con = duckdb.connect(":memory:")
    con.execute("LOAD tpch")
    con.execute(f"CALL dbgen(sf={SCALE})")
    # Keep the first ORDERS orders and their lines: the whole ontology then stays below the 10,000 objects a live object query may read.
    con.execute(f"DELETE FROM lineitem WHERE l_orderkey NOT IN (SELECT o_orderkey FROM orders ORDER BY o_orderkey LIMIT {ORDERS})")
    con.execute(f"DELETE FROM orders WHERE o_orderkey NOT IN (SELECT o_orderkey FROM orders ORDER BY o_orderkey LIMIT {ORDERS})")
    tables: list[Table] = []
    source = Source(id="tpch", title=f"TPC-H 基准数据（规模 {SCALE}，DuckDB dbgen 生成）", kind="generated", location="duckdb: CALL dbgen(sf=%s)" % SCALE, license="TPC 基准规范（数据由 DuckDB 的 tpch 扩展生成）",
                    url="https://duckdb.org/docs/stable/core_extensions/tpch.html", note="TPC-H 是批发供应商的标准基准：客户、订单、订单行、零件、供应商、国家、地区")
    for name in RAW:
        type_name, label, description, key, labels = LABELS[name]
        frame: pd.DataFrame = con.execute(f"SELECT * FROM {name}").df()
        if name == "partsupp":  # at a very small scale dbgen can pick the same supplier twice for a part; the key is (part, supplier), so keep the first
            frame = frame.drop_duplicates(["ps_partkey", "ps_suppkey"]).reset_index(drop=True)
        tables.append(Table(name=name, frame=frame, type_name=type_name, label=label, description=description, source="tpch", primary_key=key, column_labels=labels, constraints=RAW_RULES.get(name, {})))
    links = [Link(name=f"{s}_{c}", source_table=s, source_column=c, target_table=t, target_column=k, basis="declared_fk", label=f"{LABELS[s][1]}→{LABELS[t][1]}") for s, c, t, k in FKS]
    for spec in DERIVED:
        frame = con.execute(spec["sql"]).df()
        tables.append(Table(name=spec["name"], frame=frame, type_name=spec["type"], label=spec["label"], description=spec["description"], primary_key=[spec["key"]], column_labels=spec["labels"],
                            constraints=spec["rules"], derived=Derived(sql=spec["sql"], inputs=spec["inputs"], columns=spec["columns"], description=spec["description"]), kind="entity"))
        target, key = spec["of"]
        links.append(Link(name=f"{spec['name']}_{spec['key']}", source_table=spec["name"], source_column=spec["key"], target_table=target, target_column=key, basis="declared_fk",
                          label=f"{spec['label']}→{LABELS[target][1]}"))
    return Bundle(id="demo-tpch", title="供应链订单履约（TPC-H）", domain="供应链", kind="relational", ontology_name="供应链订单履约（TPC-H）",
                  summary="批发供应商的订单履约：客户下订单，订单由订单行组成，每行是某个供应商供应的某种零件；另有按供应商、客户、订单、零件汇总的四张计算表。",
                  sources=[source], tables=tables, links=links, tags=["关系型", "多表", "计算表", "血缘较深"],
                  notes=["数据由 DuckDB 的 TPC-H 生成器生成，规模很小（保留 1000 个订单及其订单行，共约 7 千个对象）；规则取自 TPC-H 规范，准时率和供应覆盖倍数两条是业务目标。",
                         "规模这么小时，同一零件可能被选到同一供应商两次；主键是（零件，供应商），所以供货关系只保留第一条。"])
